// ⚠️  FICHIER SYNCHRONISÉ — NE PAS ÉDITER À LA MAIN.
// Source : repo de l'app mobile Sapiro. Régénérer avec `npm run sync:game`.
// Toute correction doit être faite dans l'app puis re-synchronisée.
import type { Artwork, ArtMovement, ArtMedium } from "@/types";
import { getArtworkUrl } from "@/config/cdn";

/**
 * Base de données des œuvres d'art célèbres
 * ~680 œuvres réparties par mouvement artistique
 *
 * Distribution cible :
 * - Médiéval : ~30
 * - Renaissance : ~80
 * - Baroque/Dutch Golden Age : ~70
 * - Impressionnisme : ~60
 * - Post-impressionnisme : ~50
 * - Romantisme : ~40
 * - Northern Renaissance : ~50
 * - Surréalisme : ~40
 * - Néoclassicisme : ~40
 * - Cubisme : ~30
 * - Expressionnisme : ~30
 * - Sculpture : ~60 (réparti)
 * - Autres : ~50
 */

// Helper pour créer une œuvre.
// Toutes les images sont sourcées depuis Wikimedia Commons via
// scripts/fetch-artworks-wikimedia.js (cf. docs/IMAGE_CREDITS.md). Pour les
// œuvres anciennes (auteur mort + 70 ans), la reproduction reste en domaine
// public selon la doctrine PD-Art adoptée par Wikimedia.
function createArtwork(
  id: string,
  title: string,
  artist: string,
  artistFullName: string,
  artistNationality: string,
  year: number | string,
  medium: ArtMedium,
  movement: ArtMovement,
  museum: string,
  museumCity: string,
  museumCountry: string,
  description: string,
  imageSource: string = "Wikimedia Commons",
  imageLicense: string = "Public Domain",
): Artwork {
  return {
    id,
    name: title,
    type: "artwork",
    flagPath: "",
    tags: [movement, medium],
    title,
    year,
    medium,
    movement,
    artist,
    artistFullName,
    artistNationality,
    museum,
    museumCity,
    museumCountry,
    description,
    imageUrl: getArtworkUrl(movement, id),
    imageSource,
    imageLicense,
  };
}

