// ============================================
// ARTWORKS WITH IMAGES (available on CDN)
// ============================================

// Toutes les œuvres ont désormais leurs images uploadées sur le CDN Cloudflare R2
// via le script scripts/fetch-artworks-wikimedia.js + scripts/upload-artworks.js

// ============================================
// EXPORTS
// ============================================

export const allArtworks: Artwork[] = [
  ...medievalArtworks,
  ...renaissanceArtworks,
  ...baroqueArtworks,
  ...impressionismArtworks,
  ...postImpressionismArtworks,
  ...romanticismArtworks,
  ...surrealismArtworks,
  ...neoclassicismArtworks,
  ...cubismArtworks,
  ...expressionismArtworks,
  ...sculptureArtworks,
  ...otherArtworks,
];

// Fonctions de filtrage
export function getArtworksByMovement(movement: ArtMovement): Artwork[] {
  return allArtworks.filter((a) => a.movement === movement);
}

export function getArtworksByMedium(medium: ArtMedium): Artwork[] {
  return allArtworks.filter((a) => a.medium === medium);
}

export function getArtworksByMuseum(museum: string): Artwork[] {
  return allArtworks.filter((a) => a.museum.toLowerCase().includes(museum.toLowerCase()));
}

export function getArtworksByArtist(artist: string): Artwork[] {
  return allArtworks.filter((a) => a.artist.toLowerCase().includes(artist.toLowerCase()));
}

export function getArtworkById(id: string): Artwork | undefined {
  return allArtworks.find((a) => a.id === id);
}

// Œuvres avec images disponibles (pour le quiz)
// Toutes les œuvres ont leurs images sur le CDN
export function getAvailableArtworks(): Artwork[] {
  return allArtworks;
}

// Vérifier si une œuvre a une image disponible
// Toutes les œuvres ont leurs images sur le CDN
export function hasImage(id: string): boolean {
  return allArtworks.some((a) => a.id === id);
}
